const prepare = function prepareArticle({ source, voice_notes }) {
  if (typeof source !== 'string' || !source.trim()) throw new Error('An article or transcript is required.');
  if (voice_notes != null && typeof voice_notes !== 'string') throw new Error('Voice notes must be text.');
  return { source: source.replace(/\s+/g, ' ').slice(0, 9000), voice_notes: voice_notes || 'none' };
}

return $input.all().map((item,index) => ({json: prepare({source:item.json['Paste your article or transcript'], voice_notes:item.json['Voice notes (optional)']}), pairedItem:{item:index}}));
